mapper.update:
UPDATE orders
status=#{status}, payment_status=#{paymentStatus}, delivered_at=COALESCE(delivered_at,NOW()), updated_at=NOW()
WHERE id=#{id}

mapper.select:
SELECT dj.*,o.order_number,o.total_price,o.payment_status,o.status order_status,w.worker_code,w.full_name worker_name
FROM delivery_jobs dj JOIN orders o ON o.id=dj.order_id LEFT JOIN delivery_app_workers w ON w.id=dj.delivery_worker_id
 ORDER BY dj.updated_at DESC,dj.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT r.*,p.name product_name,CONCAT_WS(' ',u.first_name,u.last_name) customer_name,u.phone_number
FROM reviews r LEFT JOIN products p ON p.id=r.product_id LEFT JOIN users u ON u.id=r.user_id
 ORDER BY r.created_at DESC,r.id DESC LIMIT #{pageSize} OFFSET #{offset}
